using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var mlContext = new MLContext(seed: 0);

var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
IDataView dataView = mlContext.Data.LoadFromTextFile<CustomerDataRaw>(
    dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" string to boolean Label column
var mappingPipeline = mlContext.Transforms.CustomMapping<CustomerDataRaw, ChurnLabel>(
    (input, output) => { output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase); },
    contractName: null);

dataView = mappingPipeline.Fit(dataView).Transform(dataView);

var split = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerDataRaw.Region))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerDataRaw.Age),
        nameof(CustomerDataRaw.Income),
        "RegionEncoded",
        nameof(CustomerDataRaw.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

var model = pipeline.Fit(split.TrainSet);

var metrics = mlContext.BinaryClassification.Evaluate(
    model.Transform(split.TestSet), labelColumnName: "Label");

Console.WriteLine($"Model Accuracy: {metrics.Accuracy:P2}");
Console.WriteLine($"Model AUC:      {metrics.AreaUnderRocCurve:P2}");

var fullPipeline = mappingPipeline.Append(model);
var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerDataRaw, ChurnPrediction>(
    fullPipeline.Fit(mlContext.Data.LoadFromTextFile<CustomerDataRaw>(dataPath, hasHeader: true, separatorChar: ',')));

app.MapGet("/", () => "Churn Predictor API — POST to /predict");

app.MapPost("/predict", (CustomerInput input) =>
{
    var data = new CustomerDataRaw
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory,
        Churned = ""
    };
    var prediction = predictionEngine.Predict(data);
    return Results.Ok(new
    {
        willChurn = prediction.PredictedLabel,
        confidence = prediction.Probability
    });
});

app.Run();

